'use strict';
(function(){
const t=(k,v)=>InkLang.t(k,v);
let frame=0,tutorialFrame=0;
function showScreen(container,c,i){InkGuideRender.renderExample(container,c,i)}
function restore(){const migrated=readLocal('inkfang-defaults-version',0)!==DEFAULTS_VERSION;const saved=migrated?DEFAULT_SETUP:readLocal('inkfang-last-setup',DEFAULT_SETUP);applySetup({...DEFAULT_SETUP,...saved},$('setupForm'));saveLocal('inkfang-defaults-version',DEFAULTS_VERSION);saveLocal('inkfang-last-setup',currentSetup());$('savedSetupNote').textContent=t(migrated?'Numbers · Type · Steady · Endless. Ready when you are.':'Your last choices are ready. Start again in one click.');}

function refresh(reset=false){setupChanges();const c=currentSetup();if(reset)frame=0;const page=InkOnboarding.guidePages(c)[frame];$('guideMode').textContent=`${skillNames[c.skill].toUpperCase()} / ${c.control.toUpperCase()}`;$('guideHero').innerHTML=c.control==='voice'?`${t('YOUR VOICE.')}<br><em>${t('THEIR PROBLEM.')}</em>`:`${t('HOLD THE')}<br><em>${t('INKLANDS.')}</em>`;$('guideIntro').textContent=t('Small spells. Bigger monsters. Keep the line alive.');showScreen($('guideScreen'),c,frame);$('guideFrameNumber').textContent=`0${frame+1} / 03`;$('guideFrameTitle').textContent=t(page.title);$('guideFrameText').textContent=t(page.text);$('guidePrev').disabled=frame===0;$('guideNext').disabled=frame===2;$('guideDots').replaceChildren(...[0,1,2].map(i=>{const b=document.createElement('button');b.type='button';b.textContent=String(i+1);b.setAttribute('aria-label',`Example ${i+1}`);b.setAttribute('aria-current',i===frame?'step':'false');b.onclick=()=>{frame=i;refresh()};return b}));if(status==='setup'){$('setupStatus').textContent=t(c.music?'Two hearts · Skills charge with correct kills · Music on.':'Two hearts · Skills charge with correct kills · Music muted.')}$('startBtn').textContent=t('Play now ↗');$('quickRunSummary').textContent=`${t(c.personalOnly&&['numbers','words','spelling','mixed'].includes(c.skill)?'My list':skillNames[c.skill])} · ${t(c.control==='voice'?'Speak':'Type')} · ${t(SPEEDS[c.speed].name)} · ${c.duration?t('{n} min',{n:c.duration/60}):t('Endless')}`;const pace=paceFor(c.speed,c.control);$('speedNote').textContent=t('{pace}: about {s} seconds between arrivals. {voice}Every 20-second wave adds pressure; tougher monsters unlock as you survive.',{pace:t(pace.name),s:pace.spawn,voice:c.control==='voice'?t('Speaking gets a smaller, slower swarm. '):''});}
function tutorial(){const c=currentSetup(),p=InkOnboarding.guidePages(c)[tutorialFrame];showScreen($('tutorialScreen'),c,tutorialFrame);$('tutorialMode').textContent=t('{mode} · OPTIONAL GUIDE',{mode:`${skillNames[c.skill].toUpperCase()} / ${c.control.toUpperCase()}`});$('tutorialCount').textContent=`0${tutorialFrame+1} / 03`;$('tutorialTitle').textContent=t(p.title);$('tutorialText').textContent=t(p.text);$('tutorialBack').disabled=tutorialFrame===0;$('tutorialNext').textContent=t(tutorialFrame===2?'Done · back to play →':'Next →');}
$('setupForm').onsubmit=e=>{e.preventDefault();startRun()};$('setupForm').addEventListener('change',()=>{saveLocal('inkfang-last-setup',currentSetup());refresh(true)});
$('guidePrev').onclick=()=>{frame=Math.max(0,frame-1);refresh()};$('guideNext').onclick=()=>{frame=Math.min(2,frame+1);refresh()};$('replayTutorial').onclick=()=>{stopMicCheck();tutorialFrame=0;tutorial();$('tutorialDialog').showModal()};$('tutorialBack').onclick=()=>{tutorialFrame=Math.max(0,tutorialFrame-1);tutorial()};$('tutorialNext').onclick=()=>{if(tutorialFrame<2){tutorialFrame++;tutorial()}else{$('tutorialDialog').close();saveLocal(InkOnboarding.tutorialKey(currentSetup()),true)}};$('tutorialClose').onclick=()=>$('tutorialDialog').close();
$('resetDefaults').onclick=()=>{stopMicCheck();applySetup(DEFAULT_SETUP,$('setupForm'));saveLocal('inkfang-last-setup',currentSetup());$('savedSetupNote').textContent=t('Numbers · Type · Steady · Endless. Ready when you are.');refresh(true)};window.InkGuide={refresh,requestStart:startRun};restore();InkLang.init();refresh(true);
})();
